<script setup lang="ts">import {onMounted,ref} from 'vue';import {api,messageOf} from '@/lib/api';import {useRouter} from 'vue-router';const companies=ref<any[]>([]),catalogs=ref<any[]>([]),files=ref<File[]>([]),form=ref({company_id:'',catalog_version_id:'',name:'',period_start:'',period_end:''}),loading=ref(false),error=ref(''),router=useRouter();onMounted(async()=>{companies.value=(await api.get('/companies',{params:{per_page:100}})).data.data;catalogs.value=(await api.get('/catalogs')).data.data.filter((x:any)=>x.status==='published');form.value.company_id=companies.value[0]?.id||'';form.value.catalog_version_id=catalogs.value[0]?.id||''});function pick(e:Event){files.value=Array.from((e.target as HTMLInputElement).files||[])}async function submit(){loading.value=true;error.value='';try{const fd=new FormData();Object.entries(form.value).forEach(([k,v])=>v&&fd.append(k,v));files.value.forEach(f=>fd.append('files[]',f));const {data}=await api.post('/analyses',fd,{headers:{'Content-Type':'multipart/form-data'}});router.push(`/analises/${data.id}`)}catch(e){error.value=messageOf(e)}finally{loading.value=false}}</script><template><form class="card form-grid" @submit.prevent="submit"><div class="card-title span-2"><div><h2>Nova auditoria fiscal</h2><p>Importe XMLs, ZIPs e DANFEs correspondentes. O XML permanece a fonte exclusiva dos cálculos.</p></div></div><label>Empresa<select v-model="form.company_id" required><option v-for="c in companies" :value="c.id">{{c.legal_name}}</option></select></label><label>Catálogo fiscal<select v-model="form.catalog_version_id" required><option v-for="c in catalogs" :value="c.id">{{c.version}} — {{c.name}}</option></select></label><label class="span-2">Nome da auditoria<input v-model="form.name" required placeholder="Ex.: Competência 06/2026 — Empresa de demonstração"/></label><label>Início da competência<input v-model="form.period_start" type="date"/></label><label>Fim da competência<input v-model="form.period_end" type="date"/></label><label class="file-drop span-2">XML, ZIP ou DANFE PDF<input type="file" multiple accept=".xml,.zip,.pdf" @change="pick" required/><strong>Selecione um ou vários arquivos</strong><span>{{files.length?`${files.length} arquivo(s) selecionado(s)`:'Limites e proteção contra ZIP bomb são aplicados no processamento.'}}</span></label><p class="error span-2" v-if="error">{{error}}</p><div class="form-actions span-2"><button class="primary" :disabled="loading||!files.length">{{loading?'Enviando...':'Iniciar auditoria'}}</button></div></form></template>
